/* tiny IndexedDB blob store for audio files */
const idb=()=>new Promise((res,rej)=>{const r=indexedDB.open('rm2db',1);r.onupgradeneeded=()=>r.result.createObjectStore('aud');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
