async function radLoad(){if(RST.length&&RST._t===ST.tgt)return RST;try{
    const nm=EN[ST.tgt].toLowerCase(),H=['https://de1.api.radio-browser.info','https://nl1.api.radio-browser.info','https://at1.api.radio-browser.info'];
    const get=async q=>{for(const h of H){try{const r=await K.get('net').fetch(h+'/json/stations/search?hidebroken=true&order=clickcount&reverse=true&'+q);const j=await r.json();if(Array.isArray(j))return j}catch(e){}}return[]};
    const CC={en:['US','GB','AU','CA'],fa:['IR'],ar:['EG','SA','AE','MA'],az:['AZ'],de:['DE','AT','CH'],es:['ES','MX','AR','CO'],fr:['FR','CA','BE'],hi:['IN'],it:['IT'],ja:['JP'],ko:['KR'],pt:['BR','PT'],ru:['RU'],tr:['TR'],zh:['CN','TW','HK']}[ST.tgt]||[];
    const qs=['limit=300&languagecode='+ST.tgt,'limit=300&language='+nm,...CC.map(c=>'limit=150&countrycode='+c+'&language='+nm),...['pop','rock','jazz','news','classical','hip hop','dance','sport','oldies','folk'].map(t=>'limit=60&language='+nm+'&tag='+encodeURIComponent(t))];
    const a=(await Promise.all(qs.map(get))).flat(),b=[];
    const seen=new Set(),ok=x=>{if(!x||!(x.url_resolved||x.url)||!x.name)return false;const nmk=x.name.trim().toLowerCase();if(seen.has(nmk))return false;
      const lg=String(x.language||'').toLowerCase();if(lg&&!lg.split(/[,;/ ]+/).includes(nm)&&!lg.includes(nm))return false;
      if(!SCRIPT_OK[ST.tgt]&&SCRIPT_AR.test(x.name+(x.tags||'')))return false;
      if(ST.tgt!=='ar'&&/arab/i.test(lg)&&!lg.includes(nm))return false;seen.add(nmk);return true};
    RST=[...a,...b].filter(ok).sort((x,y)=>(y.clickcount||0)-(x.clickcount||0)).slice(0,400);RST.forEach(x=>{x._c=catOf(x)});RST._t=ST.tgt;}catch(e){}return RST}
async function tvLoad(){if(TST.length&&TST._t===ST.tgt)return TST;
  TST=(CUR[ST.tgt]||[]).map(c=>({name:c[0],url:c[1],home:c[2],grp:'⭐ '+c[3],cc:c[4],desc:c[5],curated:1,logo:'',q:'',lang:EN[ST.tgt]}));TST._t=null;
  try{const cur0=TST.slice();const r=await K.get('net').fetch('https://iptv-org.github.io/iptv/languages/'+L3[ST.tgt]+'.m3u');if(!r.ok)throw 0;const seen=new Set();
    TST=cur0.concat(parseM3U(await r.text()).filter(x=>{const k=x.name.replace(/\s*[\(\[].*?[\)\]]/g,'').trim().toLowerCase();if(!x.url||seen.has(k)||!/^https?:/.test(x.url))return false;seen.add(k);const qm=x.name.match(/(\d{3,4}p)/i);x.q=qm?qm[1]:'';{const m=(x.id||'').match(/\.([a-z]{2})(?:@|$)/i);x.cc=m?m[1].toUpperCase():''}x.name=x.name.replace(/\s*[\[\(](?:\d{3,4}p|Geo-blocked|Not 24\/7)[\]\)]/gi,'').trim();return true}));TST._t=ST.tgt; }catch(e){}return TST}

